BEGIN;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 262', 1, 'html-structure', 'HTML Page Structure', 'Tags, elements and the parts every web page has.', '[{"type":"text","text":"HTML (HyperText Markup Language) describes the **structure** of a web page. The browser reads the tags and draws the page."},{"type":"heading","text":"A minimal page"},{"type":"code","language":"html","code":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>My first page</title>\n  </head>\n  <body>\n    <h1>Hello, world!</h1>\n    <p>This is a paragraph.</p>\n  </body>\n</html>"},{"type":"text","text":"• `<head>` holds information about the page (title, meta tags, links to CSS).\n• `<body>` holds everything the user can see.\n• Most elements have an opening tag and a closing tag, like `<p>` and `</p>`."},{"type":"heading","text":"Common elements"},{"type":"code","language":"html","code":"<h2>A heading</h2>\n<a href=\"https://example.com\">A link</a>\n<img src=\"photo.jpg\" alt=\"A photo\" />\n<ul>\n  <li>First item</li>\n  <li>Second item</li>\n</ul>"},{"type":"tip","text":"Always write an `alt` text on images. Screen readers use it, and it shows if the image fails to load."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 262', 2, 'css-box-model', 'CSS Selectors and the Box Model', 'Choose elements with selectors and understand padding, border and margin.', '[{"type":"text","text":"CSS (Cascading Style Sheets) controls how HTML looks: colors, spacing and layout."},{"type":"heading","text":"Selectors"},{"type":"code","language":"css","code":"/* element selector */\np { color: #333; }\n\n/* class selector (use class=\"card\" in HTML) */\n.card { background: white; padding: 16px; }\n\n/* id selector (use id=\"title\" in HTML) */\n#title { font-size: 32px; }"},{"type":"text","text":"• An element selector styles every tag of that type.\n• A class can be used on many elements. An id should be used only once."},{"type":"heading","text":"The box model"},{"type":"text","text":"Every element is a box made of four layers, from inside to outside: **content**, **padding**, **border** and **margin**."},{"type":"code","language":"css","code":".card {\n  width: 200px;\n  padding: 16px;\n  border: 2px solid #4f46e5;\n  margin: 24px;\n}"},{"type":"text","text":"With the default setting the total width is 200 + 16 + 16 + 2 + 2 = **236px**, because padding and border are added to the width."},{"type":"tip","text":"Add `box-sizing: border-box;` so the width you set already includes the padding and border."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 262', 3, 'js-variables-functions', 'JavaScript Variables and Functions', 'let, const, and how to write functions.', '[{"type":"text","text":"JavaScript makes a page interactive. Use `let` for values that change and `const` for values that must not be reassigned."},{"type":"code","language":"js","code":"let score = 0;        // can change\nconst name = \"Dara\";  // cannot be reassigned\n\nscore = score + 10;\nconsole.log(name, score);"},{"type":"output","text":"Dara 10"},{"type":"heading","text":"Functions"},{"type":"code","language":"js","code":"function add(a, b) {\n  return a + b;\n}\n\n// arrow function (short form)\nconst double = (n) => n * 2;\n\nconsole.log(add(2, 3));\nconsole.log(double(4));"},{"type":"output","text":"5\n8"},{"type":"text","text":"• A function can take **parameters** (a, b) and give back a value with `return`.\n• Arrow functions are a shorter way to write small functions."},{"type":"tip","text":"Prefer `const` by default. Use `let` only when you really need to change the value. Avoid `var`."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 262', 4, 'js-fetch-async', 'Fetch and async/await', 'Load data from a server without freezing the page.', '[{"type":"text","text":"Loading data from a server takes time. JavaScript does not wait; it uses a **Promise** that finishes later. `async` and `await` let you write this in a clear, top-to-bottom way."},{"type":"code","language":"js","code":"async function loadUsers() {\n  try {\n    const response = await fetch(\"https://api.example.com/users\");\n    if (!response.ok) {\n      throw new Error(\"Server error: \" + response.status);\n    }\n    const users = await response.json();\n    console.log(users.length);\n  } catch (error) {\n    console.log(\"Could not load users:\", error.message);\n  }\n}\n\nloadUsers();"},{"type":"text","text":"• `await` pauses the function until the Promise finishes, but the page stays responsive.\n• `fetch` does not throw on 404 or 500, so check `response.ok` yourself.\n• Use `try / catch` to handle network errors."},{"type":"tip","text":"To run several requests at the same time, use `await Promise.all([fetch(a), fetch(b)])`."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 262', 5, 'rest-basics', 'REST API Basics', 'HTTP methods, status codes and a first request.', '[{"type":"text","text":"A REST API lets an app talk to a server with simple HTTP requests. Each URL is a **resource**, and the HTTP method says what to do with it."},{"type":"text","text":"• `GET /api/courses` reads a list.\n• `POST /api/courses` creates a new item.\n• `PATCH /api/courses/5` changes part of item 5.\n• `DELETE /api/courses/5` removes item 5."},{"type":"heading","text":"Status codes"},{"type":"text","text":"• **200** OK, **201** Created, **204** No content.\n• **400** Bad request (your input is wrong), **401** Not logged in, **403** Not allowed, **404** Not found.\n• **500** Server error."},{"type":"heading","text":"Example request"},{"type":"code","language":"js","code":"const response = await fetch(\"/api/courses\", {\n  method: \"POST\",\n  headers: {\n    \"Content-Type\": \"application/json\",\n    \"Authorization\": \"Bearer \" + token,\n  },\n  body: JSON.stringify({ title: \"Web Development\" }),\n});\nconsole.log(response.status); // 201"},{"type":"tip","text":"Send the login token in the `Authorization` header, never in the URL."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 226', 1, 'sql-select-where', 'SELECT and WHERE', 'Read rows from a table and filter them.', '[{"type":"text","text":"SQL is the language used to read and change data in a relational database. `SELECT` reads rows from a table."},{"type":"code","language":"sql","code":"-- all columns\nSELECT * FROM students;\n\n-- only some columns\nSELECT name, gpa FROM students;"},{"type":"heading","text":"Filtering with WHERE"},{"type":"code","language":"sql","code":"SELECT name, gpa\nFROM students\nWHERE gpa >= 3.5 AND city = ''Phnom Penh'';"},{"type":"text","text":"• Compare with `=`, `<>`, `<`, `>`, `<=`, `>=`.\n• Combine conditions with `AND`, `OR`, `NOT`.\n• Use `LIKE ''A%''` for names that start with A, and `IN (''A'', ''B'')` for a list."},{"type":"tip","text":"In standard SQL, text values use single quotes."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 226', 2, 'sql-order-limit', 'Sorting and Limiting Results', 'ORDER BY, LIMIT and DISTINCT.', '[{"type":"code","language":"sql","code":"SELECT name, gpa\nFROM students\nORDER BY gpa DESC, name ASC\nLIMIT 5;"},{"type":"text","text":"• `ORDER BY` sorts the result. `ASC` is low to high (the default), `DESC` is high to low.\n• `LIMIT 5` returns only the first 5 rows (the top 5 students).\n• `SELECT DISTINCT city FROM students;` shows each city only once."},{"type":"tip","text":"Without `ORDER BY`, the database may return rows in any order. Always sort when order matters."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 226', 3, 'sql-joins', 'JOINs', 'Combine rows from two tables.', '[{"type":"text","text":"A JOIN combines rows from two tables using a related column, usually a foreign key."},{"type":"text","text":"Example tables: `students(id, name)` and `enrollments(student_id, course)`."},{"type":"code","language":"sql","code":"SELECT s.name, e.course\nFROM students s\nINNER JOIN enrollments e ON e.student_id = s.id;"},{"type":"text","text":"• **INNER JOIN** keeps only rows that match in both tables.\n• **LEFT JOIN** keeps every row from the left table, even with no match (the missing side is NULL)."},{"type":"code","language":"sql","code":"-- students who are not enrolled in any course\nSELECT s.name\nFROM students s\nLEFT JOIN enrollments e ON e.student_id = s.id\nWHERE e.student_id IS NULL;"},{"type":"tip","text":"Give tables short aliases (`s`, `e`) so the query is easier to read."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 226', 4, 'sql-group-by', 'GROUP BY and HAVING', 'Count, sum and average rows in groups.', '[{"type":"text","text":"Aggregate functions calculate one value from many rows: `COUNT`, `SUM`, `AVG`, `MIN`, `MAX`."},{"type":"code","language":"sql","code":"SELECT COUNT(*) FROM students;   -- number of students\nSELECT AVG(gpa) FROM students;   -- average GPA"},{"type":"heading","text":"Grouping"},{"type":"code","language":"sql","code":"SELECT city, COUNT(*) AS total\nFROM students\nGROUP BY city\nHAVING COUNT(*) > 5\nORDER BY total DESC;"},{"type":"text","text":"• `GROUP BY` makes one result row for each group (each city).\n• `WHERE` filters rows **before** grouping. `HAVING` filters groups **after** grouping."},{"type":"tip","text":"Every column in `SELECT` must either be in `GROUP BY` or be inside an aggregate function."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 226', 5, 'normalization', 'Normalization (1NF, 2NF, 3NF)', 'Remove repeated data by splitting tables.', '[{"type":"text","text":"Normalization organizes tables to remove repeated data and prevent update mistakes."},{"type":"text","text":"• **1NF**: every cell holds one value (no lists like \"Math, Physics\" in one cell).\n• **2NF**: 1NF, and every non-key column depends on the **whole** primary key (this matters when the key has 2 or more columns).\n• **3NF**: 2NF, and no non-key column depends on another non-key column."},{"type":"heading","text":"Example"},{"type":"text","text":"Bad table: `orders(order_id, customer_id, customer_name, customer_city)`. The customer name and city depend on `customer_id`, not on `order_id`. That breaks 3NF."},{"type":"text","text":"Fix: split it into two tables."},{"type":"code","language":"sql","code":"CREATE TABLE customers (\n  customer_id  INT PRIMARY KEY,\n  name         VARCHAR(100) NOT NULL,\n  city         VARCHAR(100)\n);\n\nCREATE TABLE orders (\n  order_id     INT PRIMARY KEY,\n  customer_id  INT NOT NULL REFERENCES customers(customer_id)\n);"},{"type":"tip","text":"If you change a customer name in only one place, the data is probably well normalized."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 226', 6, 'keys-erd', 'Keys and ER Diagrams', 'Primary keys, foreign keys and relationship types.', '[{"type":"text","text":"An **ER diagram** (ERD) shows entities (tables), their attributes (columns) and the relationships between them."},{"type":"text","text":"• **Primary key**: uniquely identifies each row (cannot be NULL or repeated).\n• **Foreign key**: a column that points to the primary key of another table.\n• **Unique**: no two rows may have the same value."},{"type":"heading","text":"Relationship types"},{"type":"text","text":"• **1:1**: one user has one profile.\n• **1:N**: one teacher has many courses.\n• **N:M**: students and courses. You need a third table (a junction table) to store it."},{"type":"code","language":"sql","code":"CREATE TABLE enrollments (\n  student_id  INT REFERENCES students(id),\n  course_id   INT REFERENCES courses(id),\n  PRIMARY KEY (student_id, course_id)\n);"},{"type":"tip","text":"To turn an N:M relationship into tables, create a junction table with two foreign keys."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 201', 1, 'big-o', 'Big-O Notation', 'How running time grows when the input grows.', '[{"type":"text","text":"Big-O describes how the running time grows when the input size **n** grows. It ignores small details and shows the trend."},{"type":"text","text":"• **O(1)** constant: reading `list[0]`.\n• **O(log n)** logarithmic: binary search.\n• **O(n)** linear: looping through a list once.\n• **O(n log n)**: good sorting algorithms such as merge sort.\n• **O(n²)**: a loop inside a loop."},{"type":"code","language":"py","code":"def find_max(numbers):          # O(n): one loop\n    best = numbers[0]\n    for x in numbers:\n        if x > best:\n            best = x\n    return best\n\ndef has_duplicate(numbers):     # O(n^2): loop inside a loop\n    for i in range(len(numbers)):\n        for j in range(i + 1, len(numbers)):\n            if numbers[i] == numbers[j]:\n                return True\n    return False"},{"type":"tip","text":"Drop constants and small terms: O(2n + 5) is just O(n)."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 201', 2, 'stacks-queues', 'Stacks and Queues', 'LIFO and FIFO structures.', '[{"type":"text","text":"A **stack** is Last-In, First-Out (LIFO), like a pile of plates. A **queue** is First-In, First-Out (FIFO), like people in a line."},{"type":"code","language":"py","code":"# Stack with a list\nstack = []\nstack.append(1)\nstack.append(2)\nprint(stack.pop())      # 2 (last in, first out)\n\n# Queue with deque\nfrom collections import deque\nqueue = deque()\nqueue.append(1)\nqueue.append(2)\nprint(queue.popleft())  # 1 (first in, first out)"},{"type":"output","text":"2\n1"},{"type":"text","text":"• Stack uses: undo button, browser back, checking brackets.\n• Queue uses: print jobs, task scheduling, breadth-first search."},{"type":"tip","text":"Use `deque` for queues. `list.pop(0)` is O(n) and gets slow for big lists."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 201', 3, 'hash-maps', 'Hash Maps', 'Key and value storage with fast lookup.', '[{"type":"text","text":"A hash map (dictionary) stores **key → value** pairs. A hash function turns the key into a position, so lookup is O(1) on average."},{"type":"code","language":"py","code":"ages = {\"Dara\": 20, \"Sophea\": 19}\n\nages[\"Vanna\"] = 21          # add\nprint(ages[\"Dara\"])         # 20\nprint(ages.get(\"Bora\", 0))  # 0 (missing key, no error)\n\nfor name, age in ages.items():\n    print(name, age)"},{"type":"output","text":"20\n0\nDara 20\nSophea 19\nVanna 21"},{"type":"text","text":"• Keys must be unique and hashable (strings, numbers, tuples).\n• When two keys land in the same spot it is a **collision**. Hash maps handle it with chaining or probing.\n• The worst case lookup can be O(n), but this is rare with a good hash function."},{"type":"tip","text":"Need to count things? A dictionary is perfect: `counts[word] = counts.get(word, 0) + 1`."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 201', 4, 'recursion', 'Recursion', 'A function that calls itself, with a base case.', '[{"type":"text","text":"A recursive function calls itself on a smaller problem. It needs a **base case** (when to stop) and a **recursive case** (the smaller call)."},{"type":"code","language":"py","code":"def factorial(n):\n    if n == 0:                   # base case\n        return 1\n    return n * factorial(n - 1)  # recursive case\n\nprint(factorial(4))"},{"type":"output","text":"24"},{"type":"text","text":"How it runs: `factorial(4)` = 4 × `factorial(3)` = 4 × 3 × `factorial(2)` = ... = 4 × 3 × 2 × 1 × 1 = 24."},{"type":"text","text":"• Without a base case, the function never stops (a stack overflow error).\n• Each call uses memory on the call stack."},{"type":"tip","text":"Plain recursive Fibonacci repeats work and is O(2ⁿ). Store the results (memoization) to make it O(n)."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 201', 5, 'binary-search', 'Binary Search', 'Find a value in a sorted list in O(log n).', '[{"type":"text","text":"Binary search finds a value in a **sorted** list by checking the middle and throwing away half of the list each step. It runs in O(log n)."},{"type":"code","language":"py","code":"def binary_search(items, target):\n    low, high = 0, len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        if items[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\nprint(binary_search([2, 5, 8, 12, 16, 23], 12))"},{"type":"output","text":"3"},{"type":"text","text":"Searching 1,000,000 items takes only about 20 steps, because 2²⁰ is about one million."},{"type":"tip","text":"The list must be sorted first. On unsorted data, binary search gives wrong results."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 361', 1, 'widgets-tree', 'Widgets and the Widget Tree', 'Everything in Flutter is a widget.', '[{"type":"text","text":"In Flutter, everything you see is a **widget**: text, buttons, padding, even the whole screen. Widgets are placed inside other widgets and form a **widget tree**."},{"type":"code","language":"dart","code":"import ''package:flutter/material.dart'';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      home: Scaffold(\n        appBar: AppBar(title: const Text(''Hello'')),\n        body: const Center(child: Text(''Welcome to Flutter'')),\n      ),\n    );\n  }\n}"},{"type":"text","text":"• `MaterialApp` sets up the app. `Scaffold` gives the basic page layout (app bar, body).\n• `Center` and `Text` are small widgets combined to build the screen.\n• The `build` method describes what the widget looks like."},{"type":"tip","text":"Use `const` in front of widgets that never change. Flutter can then skip rebuilding them."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 361', 2, 'stateless-stateful', 'StatelessWidget vs StatefulWidget', 'When the screen needs to change, use state.', '[{"type":"text","text":"A **StatelessWidget** never changes after it is built. A **StatefulWidget** can change when its data (**state**) changes. Call `setState` to tell Flutter to rebuild."},{"type":"code","language":"dart","code":"class Counter extends StatefulWidget {\n  const Counter({super.key});\n\n  @override\n  State<Counter> createState() => _CounterState();\n}\n\nclass _CounterState extends State<Counter> {\n  int _count = 0;\n\n  @override\n  Widget build(BuildContext context) {\n    return ElevatedButton(\n      onPressed: () => setState(() => _count++),\n      child: Text(''Tapped $_count times''),\n    );\n  }\n}"},{"type":"text","text":"• Put values that change (like `_count`) inside the State class.\n• Changing a variable without `setState` will not update the screen."},{"type":"tip","text":"For data shared by many screens, use a state-management tool such as Provider or Riverpod instead of many `setState` calls."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 361', 3, 'layout-listview', 'Layout and ListView', 'Row, Column and long scrollable lists.', '[{"type":"text","text":"`Row` places children side by side, `Column` places them top to bottom. `ListView` shows a long scrollable list."},{"type":"code","language":"dart","code":"Column(\n  children: [\n    const Text(''My courses''),\n    Expanded(\n      child: ListView.builder(\n        itemCount: courses.length,\n        itemBuilder: (context, index) {\n          return ListTile(\n            title: Text(courses[index].title),\n            subtitle: Text(courses[index].code),\n          );\n        },\n      ),\n    ),\n  ],\n)"},{"type":"text","text":"• `ListView.builder` creates items only when they scroll into view, so it is fast for long lists.\n• Put a `ListView` inside a `Column` only with `Expanded`, or you get a layout error."},{"type":"tip","text":"Use `Padding` and `SizedBox(height: 12)` for spacing instead of empty `Text` widgets."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 361', 4, 'navigation', 'Navigation Between Screens', 'Open a new screen and go back.', '[{"type":"text","text":"Flutter keeps screens in a **stack**. `Navigator.push` opens a new screen on top, and `Navigator.pop` goes back."},{"type":"code","language":"dart","code":"// open the detail screen\nNavigator.push(\n  context,\n  MaterialPageRoute(builder: (_) => const DetailScreen()),\n);\n\n// go back\nNavigator.pop(context);"},{"type":"text","text":"• You can pass data by giving the new screen a constructor parameter: `DetailScreen(course: course)`.\n• For bigger apps, a package such as `go_router` helps with named routes and deep links."},{"type":"tip","text":"After an `await` inside a function, check `if (!context.mounted) return;` before using `context` again."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 361', 5, 'http-api', 'Calling an API with http', 'Load data from your backend.', '[{"type":"text","text":"Add the `http` package to `pubspec.yaml`, then call your backend. The result arrives later, so use `async` and `await`."},{"type":"code","language":"dart","code":"import ''dart:convert'';\nimport ''package:http/http.dart'' as http;\n\nFuture<List<dynamic>> loadCourses(String token) async {\n  final response = await http.get(\n    Uri.parse(''http://10.0.2.2:3000/api/courses''),\n    headers: {''Authorization'': ''Bearer $token''},\n  );\n\n  if (response.statusCode != 200) {\n    throw Exception(''Server error ${response.statusCode}'');\n  }\n  final data = jsonDecode(utf8.decode(response.bodyBytes));\n  return data[''courses''] as List<dynamic>;\n}"},{"type":"text","text":"• On the Android emulator, `10.0.2.2` means your computer. `localhost` would point to the emulator itself.\n• Always handle errors and show a loading state while waiting."},{"type":"tip","text":"Never put secret keys in the app. Keep them on the server."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 223', 1, 'classes-objects', 'Classes and Objects', 'A class is a blueprint, an object is one thing made from it.', '[{"type":"text","text":"A **class** is a blueprint. An **object** is one thing made from that blueprint. A class has **fields** (data) and **methods** (actions)."},{"type":"code","language":"java","code":"public class Student {\n    String name;\n    double gpa;\n\n    Student(String name, double gpa) {   // constructor\n        this.name = name;\n        this.gpa = gpa;\n    }\n\n    void introduce() {\n        System.out.println(\"Hi, I am \" + name);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Student s = new Student(\"Dara\", 3.6);\n        s.introduce();\n    }\n}"},{"type":"output","text":"Hi, I am Dara"},{"type":"text","text":"• `new` creates an object by calling the constructor.\n• `this` means the current object."},{"type":"tip","text":"Name classes with a capital letter (`Student`) and methods with a small letter (`introduce`)."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 223', 2, 'encapsulation', 'Encapsulation', 'Hide the data and control access with methods.', '[{"type":"text","text":"Encapsulation means hiding the data inside a class and giving controlled access through methods. Make fields `private` and use getters and setters."},{"type":"code","language":"java","code":"public class BankAccount {\n    private double balance;\n\n    public double getBalance() {\n        return balance;\n    }\n\n    public void deposit(double amount) {\n        if (amount <= 0) {\n            throw new IllegalArgumentException(\"Amount must be positive\");\n        }\n        balance += amount;\n    }\n}"},{"type":"text","text":"• Other code cannot set `balance` to a wrong value directly.\n• The class can check rules (like a positive amount) in one place."},{"type":"tip","text":"Start with `private` for every field. Open access only when you need it."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 223', 3, 'inheritance', 'Inheritance', 'Reuse code with extends.', '[{"type":"text","text":"Inheritance lets a class (the **subclass**) reuse the fields and methods of another class (the **superclass**) with `extends`. It models an \"is-a\" relationship: a Dog **is an** Animal."},{"type":"code","language":"java","code":"class Animal {\n    void eat() {\n        System.out.println(\"This animal eats\");\n    }\n}\n\nclass Dog extends Animal {\n    void bark() {\n        System.out.println(\"Woof!\");\n    }\n}\n\n// inside main():\nDog d = new Dog();\nd.eat();   // inherited from Animal\nd.bark();"},{"type":"output","text":"This animal eats\nWoof!"},{"type":"text","text":"• Use `super(...)` to call the superclass constructor.\n• Java allows only one superclass, but a class can implement many interfaces."},{"type":"tip","text":"Use inheritance for \"is-a\". For \"has-a\" (a Car has an Engine) use a field instead."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 223', 4, 'polymorphism', 'Polymorphism', 'The same method call, different behavior.', '[{"type":"text","text":"Polymorphism means \"many forms\": the same method call can behave differently depending on the real type of the object. A subclass can **override** a method."},{"type":"code","language":"java","code":"class Shape {\n    double area() { return 0; }\n}\n\nclass Circle extends Shape {\n    double r;\n    Circle(double r) { this.r = r; }\n    @Override\n    double area() { return Math.PI * r * r; }\n}\n\nclass Square extends Shape {\n    double side;\n    Square(double side) { this.side = side; }\n    @Override\n    double area() { return side * side; }\n}\n\n// inside main():\nShape[] shapes = { new Circle(1), new Square(2) };\nfor (Shape s : shapes) {\n    System.out.println(s.area());\n}"},{"type":"output","text":"3.141592653589793\n4.0"},{"type":"text","text":"The loop only knows about `Shape`, but Java calls the right `area()` for each object at runtime."},{"type":"tip","text":"Always add `@Override`. The compiler then warns you if the method name or parameters do not match."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
INSERT INTO lessons (course_code, position, slug, title, summary, content) VALUES ('CS 223', 5, 'abstraction-interfaces', 'Abstraction and Interfaces', 'Show what an object does, hide how.', '[{"type":"text","text":"**Abstraction** shows what an object does and hides how. In Java you use `abstract` classes and `interface`s."},{"type":"code","language":"java","code":"interface Payable {\n    void pay(double amount);\n}\n\nclass CardPayment implements Payable {\n    public void pay(double amount) {\n        System.out.println(\"Paid \" + amount + \" by card\");\n    }\n}\n\nclass CashPayment implements Payable {\n    public void pay(double amount) {\n        System.out.println(\"Paid \" + amount + \" in cash\");\n    }\n}"},{"type":"text","text":"• An **interface** lists methods a class must have. A class can implement many interfaces.\n• An **abstract class** can mix finished methods with abstract ones, and cannot be created with `new`.\n• Code that uses `Payable` does not care which payment type it gets, so you can add new types without changing it."},{"type":"tip","text":"Prefer an interface when you only need to define behavior. Use an abstract class when subclasses share code."}]'::jsonb)
  ON CONFLICT (course_code, slug) DO UPDATE SET position = EXCLUDED.position, title = EXCLUDED.title, summary = EXCLUDED.summary, content = EXCLUDED.content;
COMMIT;